fn sha256_of_fragment(o: &Honest, j: usize) -> [u8; 32] {
    sha256(&o.chunks[j / 4][(j % 4) * FRAG..(j % 4 + 1) * FRAG])
}

fn object_section(out: &mut Out, o: &Honest) {
    let s = &o.spec;
    out.section(&format!("object {}", s.name));
    out.kv("k_f", h(&s.k_f));
    out.kv("object_id", h(&s.object_id));
    out.kv("kind", s.kind.byte().to_string());
    out.kv("view_once", u8::from(s.view_once).to_string());
    out.kv("content", s.content);
    out.kv("content_len", o.content.len().to_string());
    out.kv("content_sha256", h(&sha256(&o.content)));
    out.kv("width", o.width.to_string());
    out.kv("height", o.height.to_string());
    out.kv("duration_ms", o.duration_ms.to_string());
    out.kv(
        "preview",
        if o.preview.is_empty() {
            String::new()
        } else {
            format!("hex:{}", h(&o.preview))
        },
    );
    out.kv("caption_utf8", h(s.caption.as_bytes()));
    out.kv("k_p", h(o.derived.payload.as_bytes()));
    out.kv("k_m", h(o.derived.manifest.as_bytes()));
    out.kv("commit", h(o.derived.commitment.as_bytes()));
    out.kv("class_code", o.class.code().to_string());
    out.kv("chunks", o.class.chunks().to_string());
    let id = ObjectId::from_bytes(s.object_id);
    out.kv("chunk_ad", h(&chunk_ad(&id, s.kind)));
    let n = o.chunks.len();
    for i in 0..n {
        out.kv(
            &format!("chunk_nonce[{i}]"),
            h(&chunk_nonce(i as u32, i + 1 == n)),
        );
    }
    for (j, f) in o.chunks.iter().flat_map(|c| c.chunks(FRAG)).enumerate() {
        out.kv(&format!("fragment_sha256[{j}]"), h(&sha256(f)));
    }
    out.kv("manifest_ad", h(&manifest_ad(&id, &o.derived.commitment)));
    out.kv("manifest_plaintext_head", h(&o.mp[..PREVIEW_OFFSET]));
    out.kv("manifest_plaintext_sha256", h(&sha256(&o.mp)));
    out.kv("manifest_hash", h(&o.manifest_hash));
    out.kv("manifest_blob_tail16", h(&o.blob[FRAG - 16..]));
    out.kv("descriptor", h(&o.descriptor));
    for (ordinal, gen, resend) in [
        (MANIFEST_ORDINAL, 0u8, 0u8),
        (0, 0, 0),
        (15, 1, 2),
        (i16::try_from(o.class.fragments() - 1).unwrap(), 3, 2),
    ] {
        out.kv(
            &format!("op_id[{ordinal},{gen},{resend}]"),
            h(&op_id(&id, ordinal, gen, resend)),
        );
    }
}

/// The honest objects, checked against their recipes and read back through the crate's reader.
fn objects() -> Vec<Honest> {
    let objs: Vec<Honest> = specs().iter().map(honest).collect();
    for o in &objs {
        let st = State::of(o);
        assert_eq!(
            st.run("validate"),
            Ok(()),
            "{}: the honest object validates",
            o.spec.name
        );
        for i in 0..o.chunks.len() {
            assert_eq!(
                st.run(&format!("read {i}")),
                Ok(()),
                "{}: read {i}",
                o.spec.name
            );
        }
    }
    objs
}

#[test]
fn media_object_vectors() {
    let objs = objects();
    let mut out = Out::new("media_object.txt", OBJECT_HEADER);
    out.section("constants");
    for (k, v) in [
        ("FRAG", FRAG as u64),
        ("TAG", TAG as u64),
        ("CHUNK_CT", CHUNK_CT as u64),
        ("CHUNK_PT", CHUNK_PT as u64),
        ("MANIFEST_PT", MANIFEST_PT as u64),
        ("PREVIEW_OFFSET", PREVIEW_OFFSET as u64),
        ("PREVIEW_MAX", PREVIEW_MAX as u64),
        ("HASHES_OFFSET", HASHES_OFFSET as u64),
        ("IMAGE_MAX_CONTENT", IMAGE_MAX_CONTENT),
        ("MAX_CONTENT", MAX_CONTENT),
        ("VIDEO_MAX_MS", u64::from(VIDEO_MAX_MS)),
        ("DESCRIPTOR_FIXED", DESCRIPTOR_FIXED as u64),
        ("MAX_CAPTION_BYTES", MAX_CAPTION_BYTES as u64),
    ] {
        out.kv(k, v.to_string());
    }
    out.section("labels");
    for (k, v) in [
        ("payload", labels::PAYLOAD),
        ("manifest", labels::MANIFEST),
        ("commit", labels::COMMIT),
        ("ad_chunk", labels::AD_CHUNK),
        ("ad_manifest", labels::AD_MANIFEST),
        ("op_id", labels::OP_ID),
        ("wrap", labels::WRAP_MEDIA_FILE_KEY),
    ] {
        out.kv(k, v);
    }
    out.section("classes");
    for c in SizeClass::all() {
        out.kv(
            &format!("class[{}]", c.code()),
            format!(
                "F {} chunks {} cap {} blobs {} bytes_per_relay {}",
                c.fragments(),
                c.chunks(),
                c.capacity(),
                c.fragments() + 1,
                (u64::from(c.fragments()) + 1) * FRAG as u64
            ),
        );
    }
    let mut lens: Vec<u64> = vec![0, 1];
    for c in SizeClass::all() {
        lens.extend([c.capacity() - 1, c.capacity(), c.capacity() + 1]);
    }
    lens.sort_unstable();
    lens.dedup();
    for len in lens {
        let class =
            SizeClass::for_content_len(len).map_or("none".to_string(), |c| c.code().to_string());
        out.kv(&format!("boundary[{len}]"), class);
    }
    out.section("ladder");
    for (w, h) in [
        (4032u32, 3024u32),
        (3024, 4032),
        (1080, 2400),
        (2400, 1080),
        (1920, 1080),
        (2047, 1151),
        (1000, 1001),
        (600, 400),
        (513, 300),
        (100, 50),
        (10_000, 10_000),
        (5000, 10),
    ] {
        let (iw, ih) = geometry::image_target(w, h).expect("image");
        out.kv(&format!("image[{w}x{h}]"), format!("{iw}x{ih}"));
    }
    for (w, h) in [
        (2048u32, 1536u32),
        (1536, 2048),
        (512, 336),
        (1280, 720),
        (720, 1280),
        (2048, 16),
    ] {
        let (pw, ph) = geometry::preview_target(w, h).expect("preview");
        out.kv(&format!("preview[{w}x{h}]"), format!("{pw}x{ph}"));
    }
    for o in &objs {
        object_section(&mut out, o);
    }
    let negs = negatives(&objs);
    for n in &negs {
        let base = objs
            .iter()
            .find(|o| o.spec.name == n.object)
            .expect("object");
        let mut st = State::of(base);
        for op in &n.ops {
            st.apply(op, &objs);
        }
        let got = st.run(n.step);
        assert_eq!(got, Err(n.expect), "negative {}", n.name);
        // Every step before the named one passes: `open` before `read` and `validate`.
        if n.step != "open" {
            let mut opened = State::of(base);
            for op in &n.ops {
                opened.apply(op, &objs);
            }
            assert_eq!(
                opened.run("open"),
                Ok(()),
                "negative {}: the open before its step",
                n.name
            );
        }
        out.section(&format!("negative {}", n.name));
        out.kv("object", n.object);
        for (k, op) in n.ops.iter().enumerate() {
            out.kv(&format!("op{}", k + 1), op);
        }
        out.kv("step", n.step);
        out.kv("expect", n.expect.name());
    }
    // Separation checks (cannot fail; reported apart).
    out.section("separation");
    let img = &objs[0];
    let other_key = FileKey::from_bytes(core::array::from_fn(|i| i as u8 ^ 0xff));
    let id = ObjectId::from_bytes(img.spec.object_id);
    let d = derive(&other_key, &id);
    assert_ne!(d.commitment, img.derived.commitment);
    out.kv("other_k_f", h(other_key.as_bytes()));
    out.kv("other_k_f_commit", h(d.commitment.as_bytes()));
    let other_id = ObjectId::from_bytes([0xee; 16]);
    let d2 = derive(&FileKey::from_bytes(img.spec.k_f), &other_id);
    assert_ne!(d2.payload.as_bytes(), img.derived.payload.as_bytes());
    out.kv("other_object_id", h(other_id.as_bytes()));
    out.kv("other_object_id_k_p", h(d2.payload.as_bytes()));
    out.kv("other_object_id_commit", h(d2.commitment.as_bytes()));
    assert!(negs.len() >= 50);
    // §3.7 point 5 and §3.9, read: the crate sealed each vector object's pairs once each — its n
    // chunk nonces under K_p and nonce 0 under K_m — with no violation and no repeat; every
    // negative case's re-seal was the attacker's (the tests' own AEAD), not the crate's.
    for o in &objs {
        for (key, nonces) in [
            (o.derived.payload.as_bytes(), o.chunks.len()),
            (o.derived.manifest.as_bytes(), 1),
        ] {
            let d = registry::key_digest(key);
            assert_eq!(registry::nonces_for(&d).len(), nonces, "{}", o.spec.name);
            assert!(
                registry::violations_for(&d).is_empty() && registry::repeats_for(&d).is_empty(),
                "{}: a (key, nonce) of the vectors sealed twice",
                o.spec.name
            );
        }
    }
    out.finish();
}

