// media_descriptor.txt

const DESCRIPTOR_HEADER: &str = "GHOST MEDIA descriptor vectors: the body of L0 kind 0x05 (Phase 11 design faza11-media.md §4.1, R-D1 … R-D3).
Generated and checked by client-core/media/tests/vectors.rs; replayed by the JDK replay.

  body = d_version(1) = 01 || kind(1) || flags(1) || class_code(1) || object_id(16) || key_slot(32)
         || manifest_hash(32) || caption_len(u16 BE) || caption (strict UTF-8, at most 1 024 B)
A [desc *] case with `expect = OK` lists the fields its body decodes to (and re-encodes from,
byte for byte); `expect = NON_CANONICAL` must be refused whole. The key slot is carried as it is
(zero in every L0 Kotlin builds or reads: the S2 l0Decode rule).";

fn descriptor_body(
    kind: u8,
    flags: u8,
    class: u8,
    caption: &[u8],
    caption_len: Option<u16>,
) -> Vec<u8> {
    let mut b = vec![0x01, kind, flags, class];
    b.extend_from_slice(&[0x3c; 16]);
    b.extend_from_slice(&[0u8; 32]);
    b.extend_from_slice(&[0x5d; 32]);
    b.extend_from_slice(&caption_len.unwrap_or(caption.len() as u16).to_be_bytes());
    b.extend_from_slice(caption);
    b
}

#[test]
fn media_descriptor_vectors() {
    let mut out = Out::new("media_descriptor.txt", DESCRIPTOR_HEADER);
    let max_caption = "ț".repeat(512); // 2 bytes each: exactly 1 024
    let ok_cases: Vec<(&str, Vec<u8>)> = vec![
        (
            "image_caption",
            descriptor_body(1, 0, 0, "o fotografie".as_bytes(), None),
        ),
        (
            "video_view_once_class10",
            descriptor_body(2, 1, 10, b"", None),
        ),
        (
            "video_max_caption",
            descriptor_body(2, 0, 4, max_caption.as_bytes(), None),
        ),
    ];
    let mut version2 = descriptor_body(1, 0, 0, b"x", None);
    version2[0] = 2;
    let mut trailing = descriptor_body(1, 0, 0, b"x", None);
    trailing.push(0);
    let truncated = descriptor_body(1, 0, 0, b"abcd", Some(5));
    let mut short_fixed = descriptor_body(1, 0, 0, b"", None);
    short_fixed.truncate(85);
    let too_long = descriptor_body(2, 0, 0, &[b'a'; 1025], None);
    let bad_cases: Vec<(&str, Vec<u8>)> = vec![
        ("version_2", version2),
        ("kind_0", descriptor_body(0, 0, 0, b"", None)),
        ("kind_3", descriptor_body(3, 0, 0, b"", None)),
        ("flag_bit_1", descriptor_body(2, 2, 0, b"", None)),
        ("flag_bit_7", descriptor_body(2, 0x80, 0, b"", None)),
        ("class_11", descriptor_body(2, 0, 11, b"", None)),
        ("image_class_1", descriptor_body(1, 0, 1, b"", None)),
        ("caption_1025", too_long),
        (
            "caption_overlong_utf8",
            descriptor_body(1, 0, 0, &[0xC0, 0x80], None),
        ),
        (
            "caption_surrogate",
            descriptor_body(1, 0, 0, &[0xED, 0xA0, 0x80], None),
        ),
        (
            "caption_cut_utf8",
            descriptor_body(1, 0, 0, &[0x61, 0xE2, 0x82], None),
        ),
        ("trailing_byte", trailing),
        ("caption_over_read", truncated),
        ("fixed_part_cut", short_fixed),
    ];
    for (name, body) in ok_cases {
        let d = Descriptor::decode(&body).expect(name);
        assert_eq!(*d.encode().expect("encode"), body, "{name}");
        out.section(&format!("desc {name}"));
        out.kv("body", h(&body));
        out.kv("expect", "OK");
        out.kv("kind", d.kind.byte().to_string());
        out.kv("view_once", u8::from(d.view_once).to_string());
        out.kv("class_code", d.class.code().to_string());
        out.kv("object_id", h(d.object_id.as_bytes()));
        out.kv("key_slot", h(d.key_slot.as_bytes()));
        out.kv("manifest_hash", h(&d.manifest_hash));
        out.kv("caption_utf8", h(d.caption.as_bytes()));
    }
    for (name, body) in bad_cases {
        let e = Descriptor::decode(&body).expect_err(name);
        assert_eq!(e.code(), Code::NonCanonical, "{name}");
        out.section(&format!("desc {name}"));
        out.kv("body", h(&body));
        out.kv("expect", "NON_CANONICAL");
    }
    // A filled slot encodes and decodes (the S2 surface fills it inside encrypt).
    let filled = Descriptor {
        kind: MediaKind::Image,
        view_once: false,
        class: SizeClass::SMALLEST,
        object_id: ObjectId::from_bytes([1; 16]),
        key_slot: KeySlot::from_bytes([9; 32]),
        manifest_hash: [2; 32],
        caption: String::new(),
    };
    assert_eq!(
        Descriptor::decode(&filled.encode().unwrap()).unwrap(),
        filled
    );
    assert_eq!(format!("{:?}", filled.key_slot), "KeySlot(..)");
    out.finish();
}

